{
  "message": "I will compute the total increase in unrecognized tax benefits observed over fiscal 2007 and 2008. The relationship is: ending balance at Dec 27, 2008 minus beginning balance at the start of fiscal 2007 (Dec 31, 2006). This equals the sum of the 2007 increase and the 2008 increase. Inputs: end-2008 balance = $214.4 million (source:t8c1n0); beginning-2007 balance = $70.5 million (source:t1c2n0). Units are already in millions, so no conversion is needed.",
  "tool": "calculate",
  "arguments": {
    "expression": "end_2008 - begin_2007",
    "variables": {
      "end_2008": {
        "value": 214.4,
        "source": "source:t8c1n0",
        "unit": "millions"
      },
      "begin_2007": {
        "value": 70.5,
        "source": "source:t1c2n0",
        "unit": "millions"
      }
    }
  }
}
